import re

with open('/home/bob/books/The_Unwritten_Future/THE_UNWRITTEN_FUTURE_FINAL_PRINT_READY_v9.html', 'r') as f:
    content = f.read()

# Extract content per section (between h2 headings)
# Find all h2/h3 and the text between them
sections = []

# Use a simpler approach - split by h2
parts = re.split(r'(<(?:h[1-3])\b[^>]*>.*?</(?:h[1-3])>)', content)

current_heading = "START"
current_content = ""

for part in parts:
    heading_match = re.match(r'<(?:h[1-3])\b[^>]*>(.*?)</(?:h[1-3])>', part, re.DOTALL)
    if heading_match:
        if current_heading:
            sections.append((current_heading, len(current_content.split())))
        current_heading = re.sub(r'<[^>]+>', '', heading_match.group(1)).strip()
        current_content = ""
    else:
        current_content = part

# Handle last section
if current_heading and current_content.strip():
    sections.append((current_heading, len(current_content.split())))

for heading, words in sections:
    if heading in ['By Robert Mills', 'Copyright', 'Dedication', 'Acknowledgments', 'Table of Contents', 'Table of Contents (continued)', 'Back Cover', 'About the Author']:
        continue
    if words == 0:
        continue
    print(f"  {heading}: {words} words")
"}

